      {/* Navigation */}
      <nav
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
          padding: "20px 80px",
          background: "#000",
          borderBottom: "1px solid rgba(255, 255, 255, 0.1)",
          position: "sticky",
          top: 0,
          zIndex: 100,
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
          <div
            style={{
              width: "40px",
              height: "40px",
              background: "linear-gradient(135deg, #ff6b35 0%, #ff4d00 100%)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              borderRadius: "8px",
              boxShadow: "0 4px 12px rgba(255, 107, 53, 0.3)",
            }}
          >
            <span style={{ color: "#fff", fontSize: "22px", fontWeight: "800" }}>A</span>
          </div>
          <span style={{ fontSize: "24px", fontWeight: "700", color: "#fff" }}>ASSEMBLE</span>
        </div>

        <div style={{ display: "flex", gap: "50px", alignItems: "center" }}>
          <a href="#" style={{ 
            color: "#ff6b35", 
            textDecoration: "none", 
            fontSize: "15px", 
            fontWeight: "600",
            borderBottom: "2px solid #ff6b35",
            paddingBottom: "4px",
            transition: "all 0.3s ease"
          }}>
            My Project
          </a>
          <a href="#" style={{ 
            color: "#fff", 
            textDecoration: "none", 
            fontSize: "15px", 
            fontWeight: "500",
            transition: "color 0.3s ease",
            opacity: 0.7
          }}
          onMouseEnter={(e) => e.currentTarget.style.opacity = "1"}
          onMouseLeave={(e) => e.currentTarget.style.opacity = "0.7"}
          >
            Resources
          </a>
          <a href="#" style={{ 
            color: "#fff", 
            textDecoration: "none", 
            fontSize: "15px", 
            fontWeight: "500",
            transition: "color 0.3s ease",
            opacity: 0.7
          }}
          onMouseEnter={(e) => e.currentTarget.style.opacity = "1"}
          onMouseLeave={(e) => e.currentTarget.style.opacity = "0.7"}
          >
            Library
          </a>
          <a href="#" style={{ 
            color: "#fff", 
            textDecoration: "none", 
            fontSize: "15px", 
            fontWeight: "500",
            transition: "color 0.3s ease",
            opacity: 0.7
          }}
          onMouseEnter={(e) => e.currentTarget.style.opacity = "1"}
          onMouseLeave={(e) => e.currentTarget.style.opacity = "0.7"}
          >
            About Us
          </a>
        </div>

        <div style={{ display: "flex", gap: "16px", alignItems: "center" }}>
          <span style={{ 
            color: "#fff", 
            fontSize: "15px", 
            fontWeight: "500",
            opacity: 0.9
          }}>
            admin님
          </span>
          <div style={{ position: "relative" }}>
            <button
              onClick={() => setShowProfileMenu(!showProfileMenu)}
              style={{
                background: "rgba(255, 255, 255, 0.1)",
                border: "1px solid rgba(255, 255, 255, 0.2)",
                cursor: "pointer",
                display: "flex",
                alignItems: "center",
                gap: "8px",
                fontSize: "15px",
                color: "#fff",
                fontWeight: "500",
                padding: "10px 18px",
                borderRadius: "8px",
                transition: "all 0.3s ease",
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.background = "rgba(255, 255, 255, 0.15)";
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.background = "rgba(255, 255, 255, 0.1)";
              }}
            >
              <span style={{ fontSize: "20px" }}>👤</span>
              My Profile
            </button>
            {showProfileMenu && (
              <div style={{
                position: "absolute",
                top: "calc(100% + 8px)",
                right: 0,
                background: "#1a1a1a",
                border: "1px solid rgba(255, 255, 255, 0.15)",
                borderRadius: "10px",
                padding: "8px",
                boxShadow: "0 8px 32px rgba(0,0,0,0.5)",
                minWidth: "140px"
              }}>
                <button style={{
                  width: "100%",
                  padding: "12px 16px",
                  background: "#ff6b35",
                  border: "none",
                  textAlign: "center",
                  cursor: "pointer",
                  fontSize: "15px",
                  color: "#fff",
                  borderRadius: "8px",
                  transition: "all 0.2s ease",
                  fontWeight: "600",
                }}
                onMouseEnter={(e) => {
                  e.currentTarget.style.background = "#ff4d00";
                  e.currentTarget.style.transform = "translateY(-2px)";
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.background = "#ff6b35";
                  e.currentTarget.style.transform = "translateY(0)";
                }}
                >
                  Logout
                </button>
              </div>
            )}
          </div>
        </div>
      </nav>
